mutation FlxFormTrackReply($input: FlxFormTrackReplyInput!) {
  flxFormTrackReply(input: $input) {
    submission {
      id
      trackCode
    }
    errors {
      code
      message
      field
    }
  }
}

d9f24634d21b59431deede6cf6c760e235dddc75:
query FlxForm($id: ID!) {
  flxForm(id: $id) {
    id
    title
    formType
    steps
    buttonLabel
    successTitle
    successMessage
    fields {
      id
      type
      label
      required
      placeholder
      options {
        value
        label
      }
    }
  }
}

